# Map Guide 2 · Part B World, chapters 11 to 13.
P = lambda n, g, x, **kw: dict(n=n, g=g, x=x, **kw)

CH_WORLD_B = [
dict(id="winds", part="World", t="Local winds and ocean currents", intro=(
 "Planetary winds (the trade winds, westerlies and polar easterlies) blow over half the globe. Local winds blow only over one region, and they have names that the exam matches with places. "
 "They come in three kinds. Cold winds slide down from high, cold land into warmer lowlands (Bora, Mistral). Hot, dry, dusty winds blow out of deserts (Khamsin, Sirocco, Harmattan, Loo). Warm, dry winds come down the far side of a mountain after dropping their rain on the near side; the air warms as it sinks (Chinook, Foehn). "
 "Ocean currents are rivers of water inside the ocean, pushed by winds and the earth's spin. The simple rule: warm currents flow from the equator towards the poles, and cold currents flow from the poles towards the equator. Cold currents keep the air above them dry, so they make coastal deserts (Atacama, Namib), and they bring up food for plankton and fish, so they make rich fishing grounds. Where a warm and a cold current meet, fog forms and fish gather."), P=[
 P("Bora", [14.50, 45.30], "A cold, dry, very strong north-east wind that rushes down from the mountains onto the Adriatic coast of Croatia, Slovenia and Trieste (Italy), mostly in winter. Gusts can pass 200 km/h and overturn lorries. The 2021 paper paired it correctly with the Adriatic coast.", y="2021 Q67"),
 P("Mistral", [4.80, 44.00], "A cold, dry north wind that blows down the Rhône valley in southern France to the Mediterranean, mostly in winter and spring. The valley acts like a funnel and speeds it up. It brings clear skies to Provence; farmers plant rows of cypress trees as windbreaks. The 2021 paper paired it correctly with France.", y="2021 Q67"),
 P("Khamsin", [31.20, 28.00], "A hot, dry, dusty south wind that blows over Egypt and nearby Arabia in spring, ahead of storms moving along the Mediterranean. Its name comes from the Arabic for 'fifty', the number of days it was said to blow. It can raise the temperature by 20 °C in a few hours and fill the air with sand.", y="2021 Q67"),
 P("Sirocco", [13.00, 37.80], "A hot wind from the Sahara that blows north across the Mediterranean to Sicily, southern Italy and Malta. It starts dry and dusty but picks up moisture over the sea, so it arrives hot and humid, sometimes with 'blood rain' (rain carrying red Saharan dust). In Libya it is called Ghibli and in Spain Leveche."),
 P("Harmattan", [-1.00, 12.00], "A dry, dusty north-east trade wind that blows from the Sahara over West Africa (Nigeria, Ghana and their neighbours) from November to March. It brings a dusty haze and cool nights. It is called 'the doctor' because its dry air brings relief from the damp, sticky heat of the coast."),
 P("Chinook", [-113.00, 50.50], "A warm, dry wind that blows down the eastern slopes of the Rocky Mountains into the prairies of Canada and the USA in winter and spring. The moist Pacific air drops its rain and snow on the western side; as it sinks down the eastern side it warms quickly. It can melt deep snow in hours, so it is called the 'snow eater'; it helps cattle graze in winter."),
 P("Foehn", [10.00, 47.20], "A warm, dry wind that blows down the northern slopes of the Alps into Switzerland, Austria and Germany. It works like the Chinook. It melts snow, ripens grapes and is blamed for headaches. Any wind of this type is now called a foehn wind."),
 P("Santa Ana", [-117.50, 34.00], "A hot, dry wind that blows from the high inland deserts of the Great Basin towards the coast of southern California in autumn and winter. The air warms as it sinks to the coast and squeezes through mountain passes, so it is strong and very dry. It dries out the brush and fans wildfires, such as the Los Angeles fires of January 2025 (Palisades and Eaton fires)."),
 P("Loo", [80.00, 26.50], "A strong, hot, dry west wind that blows over the plains of north and north-west India (Punjab, Haryana, Delhi, Uttar Pradesh, Bihar) in the afternoons of May and June, before the monsoon. It can push temperatures above 45 °C and causes heatstroke. It is a local hot wind, like the desert winds of Africa."),
 P("Kalbaisakhi (Nor'wester)", [88.40, 22.60], "Violent evening thunderstorms with strong winds from the north-west that hit West Bengal, Odisha, Assam and Bangladesh in April and May (the month of Baisakh; 'Kalbaisakhi' means 'calamity of Baisakh'). They bring rain that helps tea, jute and rice; in Assam they are called 'tea showers' or Bordoisila."),
 P("Mango showers", [76.30, 10.50], "Pre-monsoon thunder showers that fall in April and May along the coasts of Kerala and Karnataka, before the monsoon arrives on about 1 June. They help mangoes ripen early, hence the name. In Karnataka (Kodagu) similar showers are called 'blossom showers' or 'cherry blossom' showers because they make the coffee plants flower. Other pre-monsoon storms: Kalbaisakhi in Bengal, Bordoisila in Assam, Loo winds in the north."),
 P("Gulf Stream", [-75.00, 35.00], "A strong, warm current that flows out of the Gulf of Mexico, up the east coast of the USA, and across the Atlantic as the North Atlantic Drift. It carries tropical heat to north-west Europe, so Britain and Norway have mild winters and ice-free ports even though they are as far north as Canada's frozen coast. Scientists fear global warming is slowing this circulation."),
 P("Labrador Current", [-55.00, 50.00], "A cold current that flows south from the Arctic past Labrador and Newfoundland in Canada, carrying icebergs (the Titanic sank in its waters in 1912). Where it meets the warm Gulf Stream near Newfoundland, thick fog forms and plankton thrive, making the Grand Banks one of the world's richest fishing grounds."),
 P("Kuroshio", [135.00, 32.00], "A warm current ('black tide' in Japanese, for its deep blue, plankton-poor water) that flows north-east from the Philippines past Taiwan and the south and east coasts of Japan. It is the Pacific twin of the Atlantic's Gulf Stream: a fast western boundary current that carries tropical heat north and keeps southern Japan warm. It then turns east as the North Pacific Current. Off north-east Japan it meets the cold Oyashio."),
 P("Oyashio", [147.00, 42.00], "A cold current ('parent tide') that flows south from the Arctic past Russia's Kuril Islands to north-east Japan. Where it meets the warm Kuroshio off Japan, the mixing waters are full of plankton, making a very rich fishing ground. It is in the northern hemisphere, which was the point of the 2021 question.", y="2021 Q62"),
 P("Canaries Current", [-17.00, 27.00], "A cold current that flows south along the north-west coast of Africa past the Canary Islands. It keeps the coast cool and dry, adding to the dryness of the western Sahara, and makes the waters off Morocco and Mauritania rich in fish. It is in the northern hemisphere.", y="2021 Q62"),
 P("Humboldt (Peru) Current", [-78.00, -15.00], "A cold current that flows north along the coasts of Chile and Peru, named after the German explorer Alexander von Humboldt. Cold water welling up from below brings food for huge shoals of anchovy, making Peru one of the biggest fishing nations, and keeps the coast dry, making the Atacama. In an El Niño year, warm water spreads east, the cold current weakens, fish disappear, and India's monsoon often gets weaker."),
 P("Benguela Current", [12.00, -25.00], "A cold current that flows north along the west coast of southern Africa (South Africa and Namibia). Like the Humboldt, it brings rich fishing and makes a coastal desert: the Namib, one of the oldest deserts on earth, with its tall red dunes and foggy coast (the 'Skeleton Coast')."),
 P("Agulhas Current", [31.00, -32.00], "A strong warm current that flows south-west down the east coast of South Africa, the western boundary current of the Indian Ocean. It meets the cold Benguela near Cape Agulhas, Africa's southern tip, where its warm water swirls into the Atlantic. Its fast flow against storm waves makes this one of the most dangerous seas for ships."),
 P("West Wind Drift", [0.00, -50.00], "Also called the Antarctic Circumpolar Current: a cold current that flows from west to east right round Antarctica, pushed by the strong westerly winds (the Roaring Forties, Furious Fifties and Shrieking Sixties). It is the only current that circles the whole earth and the largest current by volume. It lies in the southern hemisphere, which was the answer to the 2021 question.", y="2021 Q62"),
 P("Somali Current", [52.00, 7.00], "A current off the coast of Somalia in the Arabian Sea. It is the only large ocean current that reverses its direction with the seasons: in the south-west monsoon (summer) it flows north-east, strong and cold with upwelling; in the north-east monsoon (winter) it flows south-west. It shows how the Indian monsoon controls the north Indian Ocean."),
]),
dict(id="hq", part="World", t="Headquarters of world bodies", intro=(
 "An international organisation is a club of countries set up by a treaty to do one job together: keep peace, fight disease, lend money, set trade rules. Each has a headquarters city, and the exam asks it again and again. "
 "Most bodies sit in a few cities. New York has the United Nations itself. Geneva, in neutral Switzerland, has the bodies for health, trade, labour, weather and the Red Cross. Washington has the two money bodies born at Bretton Woods in 1944, the IMF and the World Bank. Paris has UNESCO and the OECD; Vienna has the nuclear watchdog and OPEC; Brussels has NATO and the European Union. "
 "Asian banks sit in Asia: ADB in Manila, AIIB in Beijing, NDB in Shanghai. Regional groups sit with a member: SAARC in Kathmandu, ASEAN in Jakarta, BIMSTEC in Dhaka. For each body, learn what it does, when it was born, and India's link to it."), P=[
 P("New York", [-73.97, 40.75], "Headquarters of the United Nations (UN), set up on 24 October 1945 (UN Day) after the Second World War to keep world peace; its Charter was signed at San Francisco. It has 193 member countries; India is a founding member. Its main parts: the General Assembly (all members, one vote each); the Security Council (15 members: five permanent with a veto, the USA, UK, France, Russia and China, and ten elected for two years; India has served eight terms and wants a permanent seat); the Secretariat under the Secretary-General (António Guterres of Portugal since 2017); and ECOSOC. The International Court of Justice is in The Hague, not New York."),
 P("Geneva", [6.13, 46.23], "A Swiss city that hosts the UN's European office and many bodies. WHO (World Health Organization, 1948, 7 April is World Health Day) leads global health. WTO (World Trade Organization, 1995, replaced GATT) sets trade rules and settles trade disputes. ILO (International Labour Organization, 1919, the oldest UN agency; Nobel 1969) sets workers' rights. WMO (World Meteorological Organization; 23 March is World Meteorological Day) handles weather. The UN Human Rights Council and UNHCR (refugees) are here, as is the ICRC (Red Cross, founded 1863 by Henry Dunant)."),
 P("Washington, DC", [-77.04, 38.90], "Home of the twin 'Bretton Woods' institutions, created at a conference in Bretton Woods, USA, in July 1944. The IMF (International Monetary Fund) watches the world money system and lends to countries in a balance-of-payments crisis (when they cannot pay for imports or debts); it issues SDRs (Special Drawing Rights), its own reserve money. The World Bank lends for development projects such as roads, dams and schools, and its first loan to India came in 1949. By custom the IMF head is European and the World Bank head is American. India is a founding member of both."),
 P("Paris", [2.30, 48.85], "UNESCO (UN Educational, Scientific and Cultural Organization, 1945) runs the World Heritage list; India has 44 sites, the latest being the Maratha Military Landscapes (2025). The OECD (Organisation for Economic Co-operation and Development, 1961) is a club of rich countries that publishes economic data; India is not a member. The IEA (International Energy Agency, 1974) works on oil and energy security. The Paris Agreement on climate (2015) was signed here.", k=1),
 P("Vienna", [16.37, 48.21], "The IAEA (International Atomic Energy Agency, 1957) is the UN's nuclear watchdog: it promotes peaceful nuclear energy ('Atoms for Peace') and inspects nuclear plants to stop the making of bombs; it won the Nobel Peace Prize in 2005. OPEC (Organization of the Petroleum Exporting Countries) was founded in Baghdad in 1960 by Iran, Iraq, Kuwait, Saudi Arabia and Venezuela and moved to Vienna in 1965; it has 12 members and, with Russia and others, forms 'OPEC+', which decides how much oil to pump. The UN Office on Drugs and Crime (UNODC) is also here."),
 P("Brussels", [4.35, 50.85], "NATO (North Atlantic Treaty Organization) is a military alliance set up by the Washington Treaty of 4 April 1949 against the Soviet Union. Its key rule, Article 5, says an attack on one member is an attack on all; it has been used once, after 9/11. It had 30 members in 2022; Finland (2023) and Sweden (2024) joined after Russia invaded Ukraine, making 32. Brussels is also the main seat of the European Union (27 countries; its Parliament also meets in Strasbourg).", y="2021 Q54, 2021 Q55"),
 P("The Hague", [4.30, 52.08], "A Dutch city called the legal capital of the world. The International Court of Justice (ICJ, 1945), the UN's main court, settles disputes between countries; its 15 judges serve nine years. India won the Kulbhushan Jadhav case against Pakistan here in 2019, and India's Dalveer Bhandari is a judge. The International Criminal Court (ICC, 2002, Rome Statute) tries people for genocide and war crimes; India is not a member. The Permanent Court of Arbitration is here too."),
 P("Rome", [12.49, 41.88], "The FAO (Food and Agriculture Organization, 16 October 1945, now World Food Day) works to end hunger and publishes food data; 2023 was the International Year of Millets on India's proposal. The World Food Programme (WFP), which gives food aid in wars and disasters, won the Nobel Peace Prize in 2020. IFAD, which lends to poor farmers, is also here."),
 P("Lyon", [4.85, 45.77], "Interpol, the International Criminal Police Organization, has its headquarters in Lyon, France (since 1989). It was founded in 1923 in Vienna and has 196 member countries, the second largest body after the UN. It does not arrest anyone itself; it helps the police of member countries share information on criminals. Its best-known tool is the Red Notice, a request to police everywhere to find and hold a wanted person (there are also Blue, Yellow, Black and other colour notices; in 2025 it added a Silver Notice to trace criminals' assets). India joined in 1949, and the CBI is India's National Central Bureau, the link office with Interpol. India hosted Interpol's 90th General Assembly in New Delhi in October 2022."),
 P("London", [-0.13, 51.50], "The Commonwealth Secretariat is at Marlborough House. The Commonwealth is a voluntary group of 56 countries, most of them once ruled by Britain; India joined as a republic in 1949 (the London Declaration), and King Charles III is its head. Its leaders meet at CHOGM, and the Commonwealth Games are its sports event. The International Maritime Organization (IMO, a UN agency for shipping safety and sea pollution, MARPOL rules) is also in London."),
 P("Nairobi", [36.82, -1.23], "The capital of Kenya, the only UN headquarters city in the Global South. UNEP (UN Environment Programme) was set up in 1972 after the Stockholm conference on the human environment; it leads the UN's work on climate, pollution and nature, and publishes the Emissions Gap Report. UN-Habitat, for cities and housing, is also here. 5 June, World Environment Day, began with the Stockholm conference."),
 P("Addis Ababa", [38.75, 9.03], "The capital of Ethiopia and headquarters of the African Union (AU), set up in 2002 to replace the Organisation of African Unity (OAU, 1963). It has 55 member states. Under India's G20 presidency, the AU became a permanent member of the G20 at the New Delhi summit in September 2023. The UN Economic Commission for Africa is also here."),
 P("Manila", [121.06, 14.59], "The capital of the Philippines and headquarters of the Asian Development Bank (ADB, 1966), which lends to Asian and Pacific countries for roads, power and water. Japan and the USA are its biggest shareholders, and its president has always been Japanese. India is a founding member and one of its largest borrowers."),
 P("Beijing", [116.40, 39.90], "The AIIB (Asian Infrastructure Investment Bank) was started by China and began work in 2016 to fund roads, railways and power in Asia; China is the largest shareholder and India the second largest. The Shanghai Cooperation Organisation (SCO) has its secretariat in Beijing; despite its name it was founded in Shanghai in 2001. Its members include China, Russia, India, Pakistan (both joined 2017), Iran (2023), Belarus (2024) and four Central Asian states. Its anti-terror body RATS is in Tashkent."),
 P("Shanghai", [121.47, 31.23], "The New Development Bank (NDB), the 'BRICS bank', set up by Brazil, Russia, India, China and South Africa (agreed at the Fortaleza summit in 2014, began 2015) to fund infrastructure and green projects. Its first president was India's K. V. Kamath; Brazil's former president Dilma Rousseff now leads it. BRICS has since added Egypt, Ethiopia, Iran, the UAE and Indonesia."),
 P("Kathmandu", [85.32, 27.70], "The capital of Nepal and seat of the SAARC Secretariat (since 1987). SAARC, the South Asian Association for Regional Cooperation, was set up at Dhaka in December 1985 and has eight members: Afghanistan (joined 2007), Bangladesh, Bhutan, India, the Maldives, Nepal, Pakistan and Sri Lanka. Its last summit was in Kathmandu in 2014; the 2016 Islamabad summit was called off after the Uri attack, so India works more through BIMSTEC now."),
 P("Jakarta", [106.85, -6.20], "The capital of Indonesia and seat of the ASEAN Secretariat. ASEAN, the Association of Southeast Asian Nations, was founded by the Bangkok Declaration on 8 August 1967 by Indonesia, Malaysia, the Philippines, Singapore and Thailand; Timor-Leste became its 11th member in October 2025. India's 'Act East' policy and the India–ASEAN summits centre on it; India is also in the East Asia Summit and the ASEAN Regional Forum.", k=1),
 P("Dhaka", [90.41, 23.81], "The capital of Bangladesh and seat of the BIMSTEC Secretariat (since 2014). BIMSTEC, the Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation, was formed by the Bangkok Declaration of 1997 and links seven countries round the Bay of Bengal: Bangladesh, Bhutan, India, Myanmar, Nepal, Sri Lanka and Thailand. Its Charter came into force in 2024. The 5th summit (March 2022) was hosted online by Sri Lanka; the 6th by Thailand in Bangkok (April 2025).", y="2021 Q56"),
]),
dict(id="news", part="World", t="Places in the news, 2025–26", intro=(
 "The 2025 paper asked many questions on events: who hosted a summit, where an exercise was held, where an attack or an operation happened, what a new bridge or tunnel is called. "
 "This chapter pins the places behind the biggest stories of 2025 and 2026 and explains the story behind each. "
 "Facts marked CHECK came from news reports and should be looked up again before the exam."), P=[
 P("Pahalgam", [75.32, 34.01], "A hill resort in Anantnag district, Kashmir, on the Lidder river, the base for the Amarnath Yatra. On 22 April 2025 terrorists killed 26 people, mostly tourists, at the Baisaran meadow above the town. The Resistance Front, linked to the Lashkar-e-Taiba, was blamed. India answered by putting the Indus Waters Treaty in abeyance (on hold), closing the Attari–Wagah border and expelling Pakistani military diplomats, and then by Operation Sindoor."),
 P("Operation Sindoor targets", [71.68, 29.40], "On the night of 6–7 May 2025 the Indian armed forces struck nine terror sites in Pakistan and Pakistan-occupied Kashmir, including the Jaish-e-Mohammed headquarters at Bahawalpur (pinned here) and the Lashkar-e-Taiba centre at Muridke near Lahore. 'Sindoor' (the vermilion worn by married Hindu women) honoured the widows of Pahalgam. Four days of drone and missile exchanges followed, until a ceasefire on 10 May 2025. Colonel Sofiya Qureshi and Wing Commander Vyomika Singh briefed the media."),
 P("Chenab Bridge", [74.88, 33.15], "In Reasi, Jammu and Kashmir, on the Udhampur–Srinagar–Baramulla Rail Link (USBRL). At 359 m above the Chenab river it is the world's highest railway arch bridge, higher than the Eiffel Tower. The Prime Minister opened it on 6 June 2025 together with the Anji Khad bridge, India's first cable-stayed railway bridge, and Vande Bharat trains to Srinagar, linking the Kashmir valley to India's rail network for the first time."),
 P("New Pamban Bridge", [79.20, 9.28], "A 2.08 km rail bridge over the Palk Bay joining Rameswaram (Pamban Island) to Mandapam on the Tamil Nadu mainland. It is India's first vertical-lift sea bridge: a 72 m span rises straight up to let ships pass. The Prime Minister opened it on Ram Navami, 6 April 2025. It replaced the old Pamban bridge of 1914, India's first sea bridge, which had a scissor-type opening span."),
 P("Auli and Mahajan (Yudh Abhyas 2026)", [79.56, 30.53], "Yudh Abhyas is the yearly joint army exercise of India and the USA, held in turn in each country. The 2026 edition (22nd) was reported at Auli in Uttarakhand, a ski resort near the China border, and at the Mahajan field firing range in Bikaner, Rajasthan; some older notes wrongly say Alaska. Other India–USA exercises: Malabar (navies, with Japan and Australia), Cope India (air forces), Vajra Prahar (special forces), Tiger Triumph (tri-service).", k=1),
 P("Johannesburg (G20 2025)", [28.05, -26.20], "The largest city of South Africa, built on the Witwatersrand gold field. South Africa held the G20 presidency in 2025 and hosted the leaders' summit at Johannesburg on 22–23 November 2025, the first G20 summit on African soil; the USA stayed away. The G20 (Group of Twenty) is the main forum of 19 big economies plus the EU and, since 2023, the African Union. Recent hosts: India (New Delhi, 2023, 'Vasudhaiva Kutumbakam'), Brazil (Rio, 2024); the USA holds it in 2026.", c="South Africa"),
 P("Belém (COP30)", [-48.50, -1.46], "A port city in northern Brazil at the mouth of the Amazon. It hosted COP30, the 30th Conference of the Parties to the UN Framework Convention on Climate Change (UNFCCC), in November 2025, the first COP held in the Amazon, so forests were a main theme. COPs are the yearly world climate meetings: COP21 Paris (2015, Paris Agreement), COP26 Glasgow, COP27 Sharm el-Sheikh (loss and damage fund), COP28 Dubai (first 'global stocktake'), COP29 Baku (new climate finance goal)."),
 P("Bangkok (BIMSTEC 2025)", [100.50, 13.75], "The capital of Thailand. Thailand hosted the 6th BIMSTEC summit here on 4 April 2025, which adopted the Bangkok Vision 2030 and a maritime transport agreement; Bangladesh took over the chair. BIMSTEC itself was founded at Bangkok in 1997. India and Thailand also hold the army exercise Maitree and the naval CORPAT patrols.", c="Thailand"),
 P("Tianjin (SCO 2025)", [117.20, 39.13], "A big port city near Beijing, China. China hosted the summit of the Shanghai Cooperation Organisation (SCO) heads of state here on 31 August–1 September 2025; the Prime Minister attended, his first visit to China since 2018. India had chaired the SCO in 2023 (online summit). Kyrgyzstan holds the chair after China.", k=1),
 P("Rio de Janeiro (BRICS 2025)", [-43.20, -22.90], "Brazil's famous coastal city, below the Christ the Redeemer statue. Brazil hosted the 17th BRICS summit here on 6–7 July 2025. BRICS began as BRIC in 2009 (South Africa joined in 2010) and has since grown to ten full members with Egypt, Ethiopia, Iran, the UAE (2024) and Indonesia (2025). India holds the BRICS chair in 2026 and hosts the 18th summit.", k=1),
 P("Uzbekistan (DUSTLIK)", [64.00, 41.50], "A double-landlocked country in Central Asia (it and all its neighbours have no sea coast; Liechtenstein is the only other such country), with Tashkent as capital; Samarkand and Bukhara were great Silk Road cities, and Babur, founder of the Mughal empire, came from its Fergana valley. DUSTLIK ('friendship' in Uzbek) is the joint army exercise of India and Uzbekistan, held in turn in each country; the 2026 edition was reported in Uzbekistan. Lal Bahadur Shastri died in Tashkent in 1966 after signing the Tashkent Agreement with Pakistan.", c="Uzbekistan", k=1),
 P("Mongolia (Nomadic Elephant)", [103.00, 46.50], "A large, thinly peopled, landlocked country between Russia and China, with Ulaanbaatar as capital; Genghis Khan's empire began here. Nomadic Elephant is the yearly joint army exercise of India and Mongolia, held in turn in each country. Mongolia also hosts Khaan Quest, a multinational peacekeeping exercise in which India takes part. India calls Mongolia its 'third neighbour' and is building an oil refinery there with an Indian credit line.", c="Mongolia"),
]),
]
